insert into public.posts (type, slug, title, excerpt, published_on, published_precision, cover, icon, tone, body_html, gallery, views, is_sample, news_category, library_no, province, school, ceremony_on, ceremony_precision, categories, reading_minutes, audience, related_terms) values
  ('news', 'opening-77', 'พิธีเปิดห้องสมุดอาเซียนแห่งที่ 77 ครบ 77 จังหวัดทั่วประเทศไทย', 'กรมอาเซียน กระทรวงการต่างประเทศ ส่งมอบห้องสมุดอาเซียนแห่งสุดท้ายของโครงการ “1 จังหวัด 1 โรงเรียน 1 ห้องสมุดอาเซียน” ครบทุกจังหวัดหลังดำเนินโครงการมากว่า 11 ปี', '2026-09-01', 'day', '/images/news-77.jpg', null, null, null, '{}'::text[], 0, true, 'opening', 77, null, null, null, null, '{}'::text[], null, null, '{}'::text[]),
  ('news', 'opening-76-narathiwat', 'พิธีเปิดห้องสมุดอาเซียนแห่งที่ 76 ณ โรงเรียนนราธิวาส จังหวัดนราธิวาส', 'อธิบดีกรมอาเซียนเป็นประธานในพิธีส่งมอบห้องสมุดอาเซียนให้แก่โรงเรียนนราธิวาส จังหวัดนราธิวาส', '2025-08-25', 'day', '/images/news-76.jpg', null, null, '<p>เมื่อวันอังคารที่ 19 สิงหาคม 2568 <strong>นายพลพงศ์ วังแพน อธิบดีกรมอาเซียน กระทรวงการต่างประเทศ</strong> เป็นประธานในพิธีส่งมอบห้องสมุดอาเซียนให้แก่โรงเรียนนราธิวาส จังหวัดนราธิวาส</p>
