insert into public.glossary_terms (slug, abbr, name, full_name, definition, groups) values
  ('retreat', 'Retreat', 'Retreat', 'ASEAN Foreign Ministers'' Retreat', 'การประชุมอย่างไม่เป็นทางการของรัฐมนตรีต่างประเทศอาเซียน จัดขึ้นเพื่อหารือประเด็นสำคัญของภูมิภาคอย่างเปิดกว้าง โดยไม่มีวาระที่เป็นทางการ', array['meet']::text[]),
  ('amm-pmc', 'AMM', 'AMM-PMC', 'ASEAN Ministerial Meeting / Post Ministerial Conferences', 'การประชุมรัฐมนตรีต่างประเทศอาเซียน และการประชุมกับประเทศคู่เจรจาที่จัดต่อเนื่องกัน', array['meet']::text[]),
  ('jcm', 'JCM', 'JCM', 'ASEAN Joint Consultative Meeting', 'การประชุมหารือร่วมของเจ้าหน้าที่อาวุโสจากทั้ง 3 เสาของอาเซียน เพื่อประสานงานข้ามสาขา', array['meet']::text[]),
  ('som', 'SOM', 'SOM', 'Senior Officials'' Meeting', 'การประชุมเจ้าหน้าที่อาวุโส จัดก่อนการประชุมระดับรัฐมนตรีเพื่อเตรียมประเด็นหารือ', array['meet']::text[]),
  ('arf', 'ARF', 'ARF', 'ASEAN Regional Forum', 'เวทีหารือด้านการเมืองและความมั่นคงในภูมิภาคเอเชีย-แปซิฟิก ประชุมครั้งแรกที่กรุงเทพฯ ปี 2537', array['meet']::text[]),
  ('eas', 'EAS', 'EAS', 'East Asia Summit', 'การประชุมสุดยอดเอเชียตะวันออก เวทีหารือระดับผู้นำระหว่างอาเซียนกับประเทศสำคัญในภูมิภาค', array['meet']::text[]),
  ('apsc', 'APSC', 'APSC', 'ASEAN Political-Security Community', 'ประชาคมการเมืองและความมั่นคงอาเซียน หนึ่งใน 3 เสาหลักของประชาคมอาเซียน', array['pillar']::text[]),
  ('aec', 'AEC', 'AEC', 'ASEAN Economic Community', 'ประชาคมเศรษฐกิจอาเซียน มุ่งสู่ตลาดและฐานการผลิตเดียว', array['pillar']::text[]),
  ('ascc', 'ASCC', 'ASCC', 'ASEAN Socio-Cultural Community', 'ประชาคมสังคมและวัฒนธรรมอาเซียน ยึดประชาชนเป็นศูนย์กลาง', array['pillar']::text[]),
  ('rcep', 'RCEP', 'RCEP', 'Regional Comprehensive Economic Partnership', 'ความตกลงหุ้นส่วนทางเศรษฐกิจระดับภูมิภาค ระหว่างอาเซียนกับประเทศคู่ค้าสำคัญ', array['coop']::text[]),
  ('acai', 'ACAI', 'ACAI', 'ASEAN Centre for Active Ageing and Innovation', 'ศูนย์อาเซียนเพื่อผู้สูงวัยอย่างมีศักยภาพและนวัตกรรม ตั้งอยู่ในประเทศไทย', array['coop']::text[]),
  ('marine-debris', 'SEA', 'Marine Debris', 'ASEAN Framework of Action on Marine Debris', 'กรอบปฏิบัติการอาเซียนว่าด้วยการจัดการขยะทะเล', array['coop']::text[]);
